// src/utils/tts-sanitizer.ts
function sanitizeCurrencyForTTS(text2, options) {
  if (!text2) return text2;
  let sanitized = text2;
  if (options?.modelId === "eleven_turbo_v2_5" || options?.modelId === "eleven_flash_v2_5") {
    sanitized = sanitized.replace(/<break[^>]*>/gi, "... ");
  }
  sanitized = sanitized.replace(/\*R\$\s*([\d.,]+)\*/gi, "*$1 reais*");
  sanitized = sanitized.replace(/R\$\s*([\d.,]+)/gi, "$1 reais");
  sanitized = sanitized.replace(/(?<!R)\$\s*([\d.,]+)/gi, "$1 d\xF3lares");
  sanitized = sanitized.replace(/US\$\s*([\d.,]+)/gi, "$1 d\xF3lares");
  sanitized = sanitized.replace(/([\d.,]+)\s*USD\b/gi, "$1 d\xF3lares");
  sanitized = sanitized.replace(/€\s*([\d.,]+)/gi, "$1 euros");
  sanitized = sanitized.replace(/([\d.,]+)\s*EUR\b/gi, "$1 euros");
  sanitized = sanitized.replace(/\s+/g, " ").trim();
  return sanitized;
}
