function normalizeDeliveryStatus(rawStatus) {
  if (!rawStatus) {
    return "FAILED";
  }
  const upper = rawStatus.toUpperCase();
  if (VALID_SUCCESS_STATUSES.has(upper)) {
    return "SENT";
  }
  if (VALID_PENDING_STATUSES.has(upper)) {
    return "PENDING";
  }
  return "FAILED";
}
async function logSmsDelivery(campaign, gateway, contacts4, providerResponse) {
  const logs = contacts4.map((contact) => {
    const msgInfo = providerResponse.mensagens?.find((m) => m.Codigo_cliente === contact.id);
    if (!msgInfo) {
      return {
        campaignId: campaign.id,
        contactId: contact.id,
        smsGatewayId: gateway.id,
        status: "FAILED",
        failureReason: providerResponse.error || "Contato n\xE3o encontrado na resposta do provider",
        providerMessageId: null
      };
    }
    const status = normalizeDeliveryStatus(msgInfo.status);
    const isFailed = status === "FAILED";
    let failureReason = null;
    if (isFailed) {
      failureReason = msgInfo.error || providerResponse.error || "Status de envio n\xE3o confirmado";
    }
    return {
      campaignId: campaign.id,
      contactId: contact.id,
      smsGatewayId: gateway.id,
      status,
      failureReason,
      providerMessageId: msgInfo.id_mensagem || null
    };
  });
  if (logs.length > 0) {
    await db.insert(smsDeliveryReports).values(logs);
  }
}
