// src/lib/neurolinguistics/profile-analyzer.ts
function analyzeProfile(text2) {
  const cleanText = text2.toLowerCase();
  let visualCount = 0;
  let auditoryCount = 0;
  let kinestheticCount = 0;
  VAK_KEYWORDS.VISUAL.forEach((word) => {
    if (cleanText.includes(word)) visualCount++;
  });
  VAK_KEYWORDS.AUDITORY.forEach((word) => {
    if (cleanText.includes(word)) auditoryCount++;
  });
  VAK_KEYWORDS.KINESTHETIC.forEach((word) => {
    if (cleanText.includes(word)) kinestheticCount++;
  });
  let vakProfile = "MIXED";
  const maxVak = Math.max(visualCount, auditoryCount, kinestheticCount);
  if (maxVak > 0) {
    if (visualCount === maxVak && visualCount > auditoryCount && visualCount > kinestheticCount) vakProfile = "VISUAL";
    else if (auditoryCount === maxVak && auditoryCount > visualCount && auditoryCount > kinestheticCount) vakProfile = "AUDITORY";
    else if (kinestheticCount === maxVak && kinestheticCount > visualCount && kinestheticCount > auditoryCount) vakProfile = "KINESTHETIC";
  } else {
    vakProfile = "UNKNOWN";
  }
  const socialScores = {
    "SIGNIFICANCE": 0,
    "ACCEPTANCE": 0,
    "APPROVAL": 0,
    "INTELLIGENCE": 0,
    "PITY": 0,
    "POWER": 0,
    "UNKNOWN": 0
  };
  const words = cleanText.split(/\s+/);
  words.forEach((w) => {
    if (SOCIAL_NEED_INDICATORS.SIGNIFICANCE.pronouns.includes(w)) socialScores.SIGNIFICANCE += 2;
    if (SOCIAL_NEED_INDICATORS.ACCEPTANCE.pronouns.includes(w)) socialScores.ACCEPTANCE += 2;
  });
  SOCIAL_NEED_INDICATORS.SIGNIFICANCE.keywords.forEach((w) => {
    if (cleanText.includes(w)) socialScores.SIGNIFICANCE += 3;
  });
  SOCIAL_NEED_INDICATORS.ACCEPTANCE.keywords.forEach((w) => {
    if (cleanText.includes(w)) socialScores.ACCEPTANCE += 3;
  });
  SOCIAL_NEED_INDICATORS.APPROVAL.keywords.forEach((w) => {
    if (cleanText.includes(w)) socialScores.APPROVAL += 3;
  });
  SOCIAL_NEED_INDICATORS.INTELLIGENCE.keywords.forEach((w) => {
    if (cleanText.includes(w)) socialScores.INTELLIGENCE += 3;
  });
  SOCIAL_NEED_INDICATORS.PITY.keywords.forEach((w) => {
    if (cleanText.includes(w)) socialScores.PITY += 3;
  });
  SOCIAL_NEED_INDICATORS.POWER.keywords.forEach((w) => {
    if (cleanText.includes(w)) socialScores.POWER += 3;
  });
  let dominantNeed = "UNKNOWN";
  let maxScore = 0;
  Object.entries(socialScores).forEach(([need, score]) => {
    if (score > maxScore) {
      maxScore = score;
      dominantNeed = need;
    }
  });
  if (maxScore < 3) dominantNeed = "UNKNOWN";
  let pace = "MODERATE";
  if (vakProfile === "VISUAL") pace = "FAST";
  else if (vakProfile === "KINESTHETIC") pace = "SLOW";
  if (cleanText.length > 200) pace = "SLOW";
  if (cleanText.length < 30) pace = "FAST";
  return {
    vakProfile,
    socialNeed: dominantNeed,
    communicationPace: pace,
    confidence: maxScore > 5 ? 80 : maxScore > 0 ? 50 : 0
  };
}
