            "objetivo": "Objetivo",
            "doenca": "Doen\xE7a",
            "cirurgia": "Cirurgia",
            "nome": "Nome",
            "email": "Email",
            "telefone": "Telefone",
            "renda": "Renda",
            "cidade": "Cidade",
            "estado": "Estado",
            "sexo": "Sexo",
            "genero": "G\xEAnero",
            "gender": "Sexo",
            "sex": "Sexo"
